  activeTab: string = this.tabs[0].id; // Initialize with the first tab as active

  lastTwoSections = ['amendments', 'reportingViolations', 'monitoring'];


  constructor(public logS: LoginService, private router: Router, private formBuilder: FormBuilder, private socket: SocketService, private ss: SecureStorageService, private broadCast: BroadcastingService) {
  }

  ngOnInit() {
    this.showpolicy = false;
    this.socket.disconnect();
    this.loginForm = this.formBuilder.group({
      cEmail: ['', [Validators.required, Validators.email]],
      password: ['', [Validators.required]] //, Validators.minLength(6), Validators.pattern('^(?=.*[0-9])(?=.*[a-z])(?=.*[A-Z])(?=.*[!@#$%^&*]).{6,}$')
    });
  }





  ngAfterViewInit(): void {
    const aupchcek = localStorage.getItem('AupAgreed');

    if (aupchcek == 'Y') {
      this.agreed = true;
    }
    this.updateActiveTabOnScroll();
  }


  // @HostListener('window:scroll', [])
  onWindowScroll(scrollContainer) {
    this.updateActiveTabOnScroll();
    this.checkIfReachedEnd(scrollContainer);
  }



  scrollToSection(sectionId: string, tab, parent) {
    this.isScrollingFromClick = true;
    this.activeTab = sectionId;
    this.activtop = tab.getBoundingClientRect().top - parent.getBoundingClientRect().top;
    console.log(this.activtop);
    const section = this.getTabElementById(sectionId, this.sectionElements);
    if (section) {
      section.scrollIntoView({ behavior: 'smooth' });
    }

    if (this.timeoutId) {
      clearTimeout(this.timeoutId);
    }

    this.timeoutId = setTimeout(() => {
      this.isScrollingFromClick = false;
    }, 2000);
  }



  checkIfReachedEnd(scrollContainer) {
    const scrollPosition = scrollContainer.scrollTop + scrollContainer.clientHeight + 20;
    const scrollHeight = scrollContainer.scrollHeight;
    if (!this.reachedEnd && scrollPosition >= scrollHeight) {
      this.reachedEnd = true;
    }
  }


  getTabElementById(id: string, array): any {
    let tabelm;
    array.forEach((element) => {
      if (element.nativeElement.id == id) {
        tabelm = element;
      }
    });
    return tabelm.nativeElement;
  }

  updateActiveTabOnScroll() {
    if (this.isScrollingFromClick) return;
    let closestSectionId = '';
    let closestDistance = Infinity;
    const targetOffset = 150; // Distance from the top of the viewport for normal sections
    const viewportHeight = window.innerHeight;


    this.sectionElements.forEach((section) => {
      const rect = section.nativeElement.getBoundingClientRect();
      const sectionId = section.nativeElement.id;

      // Check if it's one of the last two sections
      if (this.lastTwoSections.includes(sectionId)) {
        // Activate when the bottom of the section is within the viewport
        if (rect.bottom <= viewportHeight && rect.bottom >= 0) {
          closestSectionId = sectionId;
        }
      } else {
        // For normal sections, check based on distance from the red area (top offset)
        const distance = Math.abs(rect.top - targetOffset);
        if (distance < closestDistance) {
          closestDistance = distance;
          closestSectionId = sectionId;
        }
      }
    });

    if (closestSectionId) {
      this.activeTab = closestSectionId;

      const tab: any = this.getTabElementById(this.activeTab, this.tabelemets);
      this.activtop = tab.getBoundingClientRect().top - this.parenntEl.nativeElement.getBoundingClientRect().top;
    }
  }

  isagreed() {
    localStorage.setItem('AupAgreed', 'Y');
    this.agreed = true;
    this.showpolicy = false;
    this.onSubmit();
  }
  async onSubmit() {

    if (!this.agreed) {
      this.showpolicy = true;
    }

    if (this.loginForm.valid) {
      if (!this.agreed) return;
      this.isloading = true;
      let res: any = await this.logS.login(this.loginForm.value, this.keepMeLogin);
      this.isloading = false;
      if (res) {
        this.userdetail = await this.ss.getUserInfo();
        this.broadCast.portMessage({ event: 'LOGIN', data: {} });
        // let id: number = await this.ss.getUserId();
        // if (id > 0) {
        //   this.socket.connect(id);
        // }
        this.loadprogress();
      }
    }
  }

  forgot() {
    this.router.navigate(['/auth/forgotpassword']);
  }

  loadprogress() {
    const intervalId = setInterval(async () => {
      this.currentprogress++;
      if (this.currentprogress > 99) {
        clearInterval(intervalId);
        try {

          this.userdetail = await this.ss.getUserInfo();
          let id: string = await this.ss.getUserId();
          if (id) {
            this.socket.connect(id);
          }


        } catch (error) {

        }
        this.router.navigate(['/user/dashboard']);
      }
    }, 15);
  }

